function swap_tradus(lang) {
    for (const key in traducciones[lang]) {
        const element = document.getElementById(key);
        if (element) {
            element.innerHTML = traducciones[lang][key];
        }
    }
}


let scrollInterval = null;

function ScrollLangs(amount) {
    scrollInterval = setInterval(() => {
        Langs.scrollBy({
            left: amount,
            behavior: "auto",
        });
    }, 10);
}


function StopScroll() {
    if (scrollInterval) {
        clearInterval(scrollInterval);
        scrollInterval = null;
    }
}